<script setup>
import { computed, ref } from 'vue';
import { useWorkspace } from '../composables/useWorkspace';
import AppIcon from '../components/AppIcon.vue';
import { formatDate } from '../lib/format';
const {state,refresh,refreshChats}=useWorkspace();
const tab=ref('all'),query=ref(''),period=ref(''),source=ref(''),filterOpen=ref(false),selected=ref(''),page=ref(1),busy=ref(false);
const labels={user:'用户',agent:'Agent',client:'来源客户端',session:'会话'};
const sourceNames={deepseek_harness_plugin:'DeepSeek Harness',openclaw_plugin:'OpenClaw',hermes_plugin:'Hermes Agent',user:'手动添加',conversation_agent:'个人助手',evolution_workbench:'记忆演化'};
const memories=computed(()=>state.memories||[]);
const sessions=computed(()=>(state.chats||[]).filter(item=>item.persisted));
function latest(items){return items.map(m=>m.updated_at||m.created_at||'').filter(Boolean).sort().at(-1)||'';}
function sessionRecords(chat){
 const ids=new Set((chat.messages||[]).flatMap(m=>(m.memory_results||[]).map(r=>r.memory?.id).filter(Boolean)));
 return memories.value.filter(m=>ids.has(m.id)||m.metadata?.thread_id===chat.id||m.metadata?.source_thread_id===chat.id||m.thread_id===chat.id||m.session_id===chat.id);
}
function agentId(record){const id=record.agent_id||record.metadata?.agent_id;return typeof id==='string'?id.trim():'';}
const agents=computed(()=>[...new Set([...memories.value,...sessions.value].map(agentId).filter(Boolean))].map(id=>{
 const records=memories.value.filter(m=>agentId(m)===id),chats=sessions.value.filter(m=>agentId(m)===id);
 return {key:'agent:'+id,id,name:id,type:'agent',source:'',records,updated:latest([...records,...chats]),sessionCount:chats.length};
}));
const entities=computed(()=>[
 {key:'user:'+state.user,id:state.user,name:state.user,type:'user',source:'',records:memories.value,updated:latest([...memories.value,...sessions.value]),sessionCount:sessions.value.length},
 ...[...new Set(memories.value.map(m=>m.source).filter(Boolean))].map(value=>{const records=memories.value.filter(m=>m.source===value);return {key:'client:'+value,id:value,name:sourceNames[value]||value,type:'client',source:value,records,updated:latest(records)};}),
 ...agents.value,
 ...sessions.value.map(chat=>({key:'session:'+chat.id,id:chat.id,name:chat.title||'未命名会话',type:'session',source:'',records:sessionRecords(chat),updated:chat.updated_at,chat})),
]);
const sources=computed(()=>[...new Set(memories.value.map(m=>m.source).filter(Boolean))]);
const filtered=computed(()=>entities.value.filter(item=>
 (tab.value==='all'||item.type===tab.value)&&
 (!query.value.trim()||[item.id,item.name,item.source].join(' ').toLowerCase().includes(query.value.trim().toLowerCase()))&&
 (!source.value||item.source===source.value||item.records.some(m=>m.source===source.value))&&
 (!period.value||(item.updated&&Date.parse(item.updated)>=Date.now()-Number(period.value)*86400000))
));
const rows=computed(()=>filtered.value.slice(0,20*page.value));
const detail=computed(()=>entities.value.find(item=>item.key===selected.value));
function reset(){query.value='';source.value='';period.value='';tab.value='all';page.value=1;}
async function reload(){if(busy.value)return;busy.value=true;try{await Promise.all([refresh(),refreshChats()]);}finally{busy.value=false;}}
function date(value){return value?formatDate(value):'暂无活动';}
</script>
<template>
 <div class="page connections-page">
  <div class="page-heading"><div><h1>接入管理</h1><p>查看当前空间的用户、记忆来源与会话活动。</p></div><RouterLink to="/install" class="button">接入指南 <AppIcon name="external"/></RouterLink></div>
  <div class="connections-toolbar"><label class="connections-search"><AppIcon name="search"/><input v-model="query" aria-label="搜索接入实体" placeholder="搜索名称、用户 ID、来源或会话 ID"/></label><button class="button" :aria-expanded="filterOpen" @click="filterOpen=!filterOpen">筛选{{ source?' · 1':'' }}</button><select v-model="period" aria-label="活动时间范围"><option value="">全部时间</option><option value="1">最近一天</option><option value="7">最近七天</option><option value="30">最近三十天</option></select><button class="icon-button" aria-label="刷新接入记录" :disabled="busy||state.sending" @click="reload"><AppIcon name="refresh"/></button></div>
  <div v-if="filterOpen" class="connections-filters"><label>记忆来源 <select v-model="source" aria-label="筛选接入来源"><option value="">全部来源</option><option v-for="value in sources" :key="value" :value="value">{{ sourceNames[value]||value }}</option></select></label><button class="text-button" @click="source=''">清除来源</button></div>
  <div class="connections-tabrow"><div role="group" aria-label="实体类型" class="connections-tabs"><button v-for="(label,key) in {all:'全部',user:'用户',agent:'Agents',client:'来源客户端',session:'会话'}" :key="key" :class="{active:tab===key}" :aria-pressed="tab===key" @click="tab=key;page=1">{{ label }}<span>{{ key==='all'?entities.length:entities.filter(item=>item.type===key).length }}</span></button></div><button class="text-button" @click="reset">重置筛选</button></div>
  <div class="connections-layout" :class="{inspecting:!!detail}"><section class="panel"><div class="connections-scope"><span>{{ state.user }} · {{ filtered.length }} 个实体</span><span>已加载 {{ memories.length }} 条记忆 · {{ sessions.length }} 个服务端会话</span></div><div class="table-scroll"><table class="connections-table"><thead><tr><th>名称 / ID</th><th>类型</th><th>关联记忆</th><th>最近活动</th><th/></tr></thead><tbody><tr v-for="item in rows" :key="item.key" :class="{selected:detail?.key===item.key}"><td><button class="connections-entity" @click="selected=item.key"><AppIcon :name="item.type==='session'?'chat':item.type==='client'?'layers':'overview'"/><span><strong>{{ item.name }}</strong><small>{{ item.id }}</small></span></button></td><td><span class="badge">{{ labels[item.type] }}</span></td><td>{{ item.records.length }}</td><td>{{ date(item.updated) }}</td><td><button class="icon-button" :aria-label="`查看${item.name}详情`" @click="selected=item.key"><AppIcon name="chevron"/></button></td></tr><tr v-if="!rows.length"><td colspan="5" class="empty">{{ state.loading?'正在同步接入信息…':tab==='agent'?'暂无 Agent 记录':'没有符合条件的接入记录' }}</td></tr></tbody></table></div><div class="connections-list-footer"><span>来源活动按已有记忆与会话记录汇总</span><button v-if="rows.length<filtered.length" class="button small" @click="page++">加载更多</button></div></section>
  <aside v-if="detail" class="panel connections-detail"><div class="panel-heading"><h2>实体详情</h2><button class="icon-button" aria-label="关闭接入详情" @click="selected=''">×</button></div><div class="connections-detail-body"><span class="badge">{{ labels[detail.type] }}</span><h3>{{ detail.name }}</h3><code>{{ detail.id }}</code><dl><dt>所属空间</dt><dd>{{ state.user }}</dd><dt>最近活动</dt><dd>{{ date(detail.updated) }}</dd><dt>关联记忆</dt><dd>{{ detail.records.length }} 条</dd><template v-if="detail.type==='user'"><dt>服务端会话</dt><dd>{{ detail.sessionCount }} 个</dd></template><template v-if="detail.chat"><dt>会话消息</dt><dd>{{ detail.chat.messages.length }} 条</dd></template></dl><RouterLink v-if="detail.type==='session'" class="button full" :to="{name:'assistant',query:{thread:detail.id}}">打开来源会话 <AppIcon name="external"/></RouterLink><h4>关联记忆</h4><div v-if="!detail.records.length" class="subtle">暂无关联记忆</div><RouterLink v-for="record in detail.records.slice(0,12)" :key="record.id" class="connections-record" :to="{name:'memories',query:{record:record.id}}"><span>{{ record.content }}</span><AppIcon name="chevron"/></RouterLink></div></aside></div>
 </div>
</template>
<style scoped>
.connections-page{max-width:1500px}.connections-toolbar{display:flex;align-items:center;gap:9px;margin:26px 0 12px}.connections-search{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:6px;padding:9px 12px;flex:1;background:var(--surface);color:var(--muted)}.connections-search input{border:0;outline:none;background:transparent;color:var(--ink);width:100%;min-width:0;font-size:12px}.connections-search:focus-within{border-color:var(--blue)}select{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:9px;font-size:11px}.connections-filters{display:flex;align-items:center;gap:20px;background:var(--surface);padding:12px;border:1px solid var(--line);border-radius:7px;margin-bottom:12px;font-size:12px;color:var(--muted)}.connections-filters label{display:flex;align-items:center;gap:10px}.connections-tabrow{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:25px}.connections-tabs{display:flex;border:1px solid var(--line);border-radius:6px;overflow:hidden;flex-wrap:wrap}.connections-tabs button{background:transparent;border:0;border-right:1px solid var(--line);padding:8px 14px;color:var(--muted);font-size:11px;display:flex;gap:10px;align-items:center}.connections-tabs button:last-child{border:0}.connections-tabs button.active{background:var(--accent-soft);color:#d7c0f4}.connections-tabs button>span{font-size:10px;opacity:.65}.connections-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;align-items:start}.connections-layout.inspecting{grid-template-columns:minmax(0,1fr) 310px}.connections-scope{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:16px 18px;color:var(--muted);font-size:10px}.connections-table{width:100%;border-collapse:collapse;text-align:left;min-width:600px}.connections-table th{font-size:10px;font-weight:500;background:var(--surface-raised);color:var(--muted);padding:11px 18px;border-block:1px solid var(--line)}.connections-table td{padding:13px 18px;border-bottom:1px solid var(--line);color:var(--text-secondary);font-size:11px}.connections-table tr.selected{background:var(--accent-soft)}.connections-entity{display:flex;align-items:center;gap:12px;background:transparent;border:0;padding:0;text-align:left;color:inherit;max-width:300px}.connections-entity>i{color:var(--muted)}.connections-entity strong{font-size:12px;font-weight:500;display:block;color:var(--ink);overflow-wrap:anywhere}.connections-entity small{display:block;color:var(--muted);font-size:10px;margin-top:4px;overflow-wrap:anywhere}.connections-list-footer{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;color:var(--muted);font-size:10px}.connections-detail-body{padding:0 20px 20px}.connections-detail h3{font-size:16px;font-weight:500;overflow-wrap:anywhere}.connections-detail code{font-size:10px;color:var(--muted);overflow-wrap:anywhere}.connections-detail dl{display:grid;grid-template-columns:95px 1fr;gap:12px;font-size:11px;margin:24px 0;color:var(--muted)}.connections-detail dd{margin:0;color:var(--text-secondary)}.connections-detail h4{font-size:12px;font-weight:500;margin:26px 0 12px}.connections-record{display:flex;align-items:center;gap:10px;border-top:1px solid var(--line);padding:12px 0;font-size:11px;color:var(--text-secondary)}.connections-record>span{flex:1;overflow-wrap:anywhere}.connections-record svg{width:12px}.connections-record:hover{color:var(--blue)}@media(max-width:1100px){.connections-layout.inspecting{grid-template-columns:1fr}.connections-toolbar{flex-wrap:wrap}.connections-search{flex-basis:100%}.connections-tabrow{align-items:flex-start}.connections-tabs button{padding:8px 10px}}
</style>
